namespace bb::gui {
	thread_local bool            gui_used = false;
	thread_local buffer<gadget*> gadgets;
	thread_local buffer<menu*>   menus;
	thread_local buffer<node*>   nodes;
	thread_local buffer<icon_strip*> strips;

	static thread_local int desktop = 0;

	// DesktopBuffer does nothing: this is the one pixel that drawing there goes to, so the real desktop is never touched.
	static thread_local int desktop_scratch = 0;

	char* copy_string(const char* s)
	{
		size_t length = s ? strlen(s) : 0;
		char*  out    = static_cast<char*>(bb_malloc(length + 1));
		if (!out) {
			bb_runtime_error("Out of memory.");
		}
		if (length) {
			memcpy(out, s, length);
		}
		out[length] = 0;
		return out;
	}

	char* string_result(const char* s)
	{
		return bb_copy(s ? s : "", s ? strlen(s) : 0);
	}

	void set_string(char*& field, const char* value)
	{
		char* fresh = copy_string(value);
		bb_free(field);
		field = fresh;
	}

	void gui_error(const char* message)
	{
		bb_runtime_error(message);
		exit(1);
	}

	gadget* gadget_of(int handle)
	{
		int index = handle - gadget_base - 1;
		if ((index < 0) || (uint32_t(index) >= gadgets.size) || !gadgets[uint32_t(index)]->used) {
			return nullptr;
		}
		return gadgets[uint32_t(index)];
	}

	gadget* need_gadget(int handle, const char* what)
	{
		gadget* g = gadget_of(handle);
		if (!g) {
			char message[128];
			snprintf(message, sizeof(message), "%s: the gadget does not exist.", what);
			gui_error(message);
		}
		return g;
	}

	gadget* need_kind(int handle, int kind, const char* what)
	{
		gadget* g = need_gadget(handle, what);
		if (g->kind != kind) {
			char message[128];
			snprintf(message, sizeof(message), "%s: this is not the right kind of gadget.", what);
			gui_error(message);
		}
		return g;
	}

	int gadget_of_surface(int surface)
	{
		if (!surface) {
			return 0;
		}
		for (uint32_t i = 0; i < gadgets.size; i++) {
			gadget* g = gadgets[i];
			if (g && g->used && (g->kind == K_WINDOW) && (g->surface == surface)) {
				return handle_of(g);
			}
		}
		return 0;
	}

	int handle_of(gadget const* g)
	{
		for (uint32_t i = 0; i < gadgets.size; i++) {
			if (gadgets[i] == g) {
				return int(i) + gadget_base + 1;
			}
		}
		return 0;
	}

	menu* menu_of(int handle)
	{
		int index = handle - menu_base - 1;
		if ((index < 0) || (uint32_t(index) >= menus.size) || !menus[uint32_t(index)]->used) {
			return nullptr;
		}
		return menus[uint32_t(index)];
	}

	node* node_of(int handle)
	{
		int index = handle - node_base - 1;
		if ((index < 0) || (uint32_t(index) >= nodes.size) || !nodes[uint32_t(index)]->used) {
			return nullptr;
		}
		return nodes[uint32_t(index)];
	}

	icon_strip* strip_of(int handle)
	{
		int index = handle - strip_base - 1;
		if ((index < 0) || (uint32_t(index) >= strips.size) || !strips[uint32_t(index)]->used) {
			return nullptr;
		}
		return strips[uint32_t(index)];
	}

	static int new_handle(gadget* g)
	{
		gadgets.push(g);
		return int(gadgets.size) + gadget_base;
	}

	// The desktop is the group of the windows. It is as big as the window of the program.
	void screen_size(int* w, int* h);

	// The desktop is as big as the display (the window of Graphics where there is no display), which is what the windows that
	// are drawn on it have to fit in.
	int desktop_handle()
	{
		if (!desktop) {
			gadget* g  = new gadget();
			g->used    = true;
			g->kind    = K_DESKTOP;
			g->visible = true;
			int width = 0, height = 0;
			screen_size(&width, &height);
			g->w = g->cw = width > 0 ? width : 1024;
			g->h = g->ch = height > 0 ? height : 768;
			desktop = new_handle(g);
		}
		return desktop;
	}

	// The size of the primary display, with the area under the task bar and start menu, in the units of the program, which is
	// what ClientWidth and ClientHeight tell for the desktop and what its windows have to fit in. A display with a high density
	// of pixels has fewer units than pixels: one of 1920 by 1080 pixels at 150 % is a desktop of 1280 by 720, as the original
	// sees it, whose windows the system scales.
	void screen_size(int* w, int* h)
	{
		*w = bb_graphics_width();
		*h = bb_graphics_height();
		if (SDL_WasInit(SDL_INIT_VIDEO)) {
			SDL_DisplayID display = SDL_GetPrimaryDisplay();
			SDL_Rect      bounds{};
			float         units = bb_gui_desktop_scale();
			units               = units > 0.0f ? units : 1.0f;
			if (display && SDL_GetDisplayBounds(display, &bounds) && (bounds.w > 0) && (bounds.h > 0)) {
				*w = int(lroundf(float(bounds.w) / units));
				*h = int(lroundf(float(bounds.h) / units));
			} else if (const SDL_DisplayMode* mode = display ? SDL_GetDesktopDisplayMode(display) : nullptr) {
				if ((mode->w > 0) && (mode->h > 0)) {
					*w = int(lroundf(float(mode->w) / units));
					*h = int(lroundf(float(mode->h) / units));
				}
			}
		}
	}

	// Nothing can be drawn on, or read from, the desktop of the computer. Programs get a buffer that is one black pixel
	// every time they ask, which is dropped when they ask again.
	int desktop_buffer()
	{
		if (!desktop_scratch) {
			offscreen_hold hold;
			desktop_scratch = bb_create_image(1, 1, 1);
		}
		int buffer = bb_image_buffer(desktop_scratch, 0);
		int saved  = bb_graphics_buffer();
		bb_set_buffer(buffer);
		bb_clscolor(0, 0, 0);
		bb_cls();
		bb_set_buffer(saved);
		return buffer;
	}

	static bool is_group(int kind)
	{
		return (kind == K_DESKTOP) || (kind == K_WINDOW) || (kind == K_PANEL) || (kind == K_TABBER) || (kind == K_CANVAS);
	}

	void window_decoration(gadget const& g, int* left, int* top, int* right, int* bottom)
	{
		int frame = window_frame(g);
		*left = *right = frame;
		*top    = frame + ((g.style & 1) ? title_bar_height(g) : 0) + ((g.style & 4) ? menu_height : 0);
		*bottom = frame + ((g.style & 8) ? status_height : 0);
	}

	// Where the children of a gadget are, relative to the gadget.
	void client_rect(int handle, int* x, int* y, int* w, int* h)
	{
		gadget* g = gadget_of(handle);
		*x = *y = *w = *h = 0;
		if (!g) {
			return;
		}
		switch (g->kind) {
		case K_WINDOW: {
			int l, t, r, b;
			window_decoration(*g, &l, &t, &r, &b);
			*x = l;
			*y = t;
			*w = g->w - l - r;
			*h = g->h - t - b;
			break;
		}
		case K_TABBER:
			tab_client_rect(*g, x, y, w, h);
			break;
		default:
			*w = g->w;
			*h = g->h;
			break;
		}
		if (*w < 0) {
			*w = 0;
		}
		if (*h < 0) {
			*h = 0;
		}
	}

	void absolute_position(int handle, int* x, int* y)
	{
		int ax = 0, ay = 0;
		for (int h = handle; h;) {
			gadget* g = gadget_of(h);
			if (!g) {
				break;
			}
			ax += g->x;
			ay += g->y;
			if (g->parent) {
				int cx, cy, cw, ch;
				client_rect(g->parent, &cx, &cy, &cw, &ch);
				ax += cx;
				ay += cy;
			}
			h = g->parent;
		}
		*x = ax;
		*y = ay;
	}

	void absolute_client(int handle, int* x, int* y)
	{
		absolute_position(handle, x, y);
		int cx, cy, cw, ch;
		client_rect(handle, &cx, &cy, &cw, &ch);
		*x += cx;
		*y += cy;
	}

	bool shown(int handle)
	{
		for (int h = handle; h;) {
			gadget* g = gadget_of(h);
			if (!g || !g->visible) {
				return false;
			}
			if ((g->kind == K_WINDOW) && g->minimized) {
				return false;
			}
			h = g->parent;
		}
		return true;
	}

	int window_of(int handle)
	{
		for (int h = handle; h;) {
			gadget* g = gadget_of(h);
			if (!g) {
				return 0;
			}
			if (g->kind == K_WINDOW) {
				return h;
			}
			h = g->parent;
		}
		return 0;
	}

	void update_client(int handle)
	{
		gadget* g = gadget_of(handle);
		if (!g || !is_group(g->kind)) {
			return;
		}
		int cx, cy, cw, ch;
		client_rect(handle, &cx, &cy, &cw, &ch);
		if ((cw == g->cw) && (ch == g->ch)) {
			return;
		}
		g->cw = cw;
		g->ch = ch;
		for (uint32_t k = 0; k < g->kids.size; k++) {
			gadget* kid = gadget_of(g->kids[k]);
			if (kid) {
				perform_layout(*kid);
			}
		}
	}

	void lock_layout(gadget& g)
	{
		g.ox = g.x;
		g.oy = g.y;
		g.ow = g.w;
		g.oh = g.h;
		gadget* parent = gadget_of(g.parent);
		if (parent) {
			int cx, cy;
			client_rect(g.parent, &cx, &cy, &g.gw, &g.gh);
			if (g.gw < 1) {
				g.gw = 1;
			}
			if (g.gh < 1) {
				g.gh = 1;
			}
		}
	}

	// Moves and sizes a gadget to follow its group, the way that its layout says.
	void perform_layout(gadget& g)
	{
		gadget* parent = gadget_of(g.parent);
		if (!parent || (g.kind == K_WINDOW)) {
			return;
		}
		int cx, cy, gw, gh;
		client_rect(g.parent, &cx, &cy, &gw, &gh);
		if (gw < 1) {
			gw = 1;
		}
		if (gh < 1) {
			gh = 1;
		}
		int x = g.x, x2 = g.x + g.w;
		if (g.left || g.right) {
			if (g.left == 1) {
				x = g.ox;
			} else if (g.left == 2) {
				x = gw * g.ox / g.gw;
			}
			if (g.right == 1) {
				x2 = g.ox + g.ow - g.gw + gw;
			} else if (g.right == 2) {
				x2 = gw * (g.ox + g.ow) / g.gw;
			}
			if (!g.left) {
				x = x2 - g.ow;
			} else if (!g.right) {
				x2 = x + g.ow;
			}
		} else {
			x  = gw * (g.ox + g.ow / 2) / g.gw - g.ow / 2;
			x2 = x + g.ow;
		}
		int y = g.y, y2 = g.y + g.h;
		if (g.top || g.bottom) {
			if (g.top == 1) {
				y = g.oy;
			} else if (g.top == 2) {
				y = gh * g.oy / g.gh;
			}
			if (g.bottom == 1) {
				y2 = g.oy + g.oh - g.gh + gh;
			} else if (g.bottom == 2) {
				y2 = gh * (g.oy + g.oh) / g.gh;
			}
			if (!g.top) {
				y = y2 - g.oh;
			} else if (!g.bottom) {
				y2 = y + g.oh;
			}
		} else {
			y  = gh * (g.oy + g.oh / 2) / g.gh - g.oh / 2;
			y2 = y + g.oh;
		}
		set_shape(handle_of(&g), x, y, x2 - x, y2 - y);
	}

	// Sets where a gadget is, which tells what is in it if the size of what is in it changed.
	void set_shape(int handle, int x, int y, int w, int h)
	{
		gadget* g = gadget_of(handle);
		if (!g) {
			return;
		}
		bool moved = (g->x != x) || (g->y != y), sized = (g->w != w) || (g->h != h);
		g->x = x;
		g->y = y;
		g->w = w;
		g->h = h;
		if (sized) {
			update_client(handle);
		}
		if (g->kind == K_WINDOW) {
			if (g->surface && (moved || sized)) {
				bb_gui_window_set_shape(g->surface, x, y, w, h);
			}
			if (moved && g->visible) {
				post_to(event_window_move, handle, 0, x, y);
			}
			if (sized && g->visible) {
				post_to(event_window_size, handle, 0, w, h);
			}
		}
		dirty();
	}

	////////////////////////////////////////////////////////////////////////////
	// Making and freeing
	////////////////////////////////////////////////////////////////////////////
	int create_gadget(int kind, int style, int group, const char* what)
	{
		gui_used = true;
		ensure_graphics();
		if ((kind == K_WINDOW) && !group) {
			group = desktop_handle();
		}
		gadget* parent = gadget_of(group);
		if (!parent) {
			char message[128];
			snprintf(message, sizeof(message), "%s: the group does not exist.", what);
			gui_error(message);
		}
		if (!is_group(parent->kind)) {
			char message[128];
			snprintf(message, sizeof(message), "%s: the gadget can't hold other gadgets.", what);
			gui_error(message);
		}
		if ((kind != K_WINDOW) && (parent->kind == K_DESKTOP)) {
			char message[128];
			snprintf(message, sizeof(message), "%s: only windows can be on the desktop.", what);
			gui_error(message);
		}
		gadget* g = new gadget();
		g->used   = true;
		g->kind   = kind;
		g->style  = style;
		g->parent = group;
		g->text   = copy_string("");
		int handle = new_handle(g);
		parent->kids.push(handle);
		int cx, cy;
		client_rect(handle, &cx, &cy, &g->cw, &g->ch);
		lock_layout(*g);
		dirty();
		return handle;
	}

	void free_gadget_tree(int handle)
	{
		gadget* g = gadget_of(handle);
		if (!g) {
			return;
		}
		while (g->kids.size) {
			free_gadget_tree(g->kids[g->kids.size - 1]);
			g = gadget_of(handle);
			if (!g) {
				return;
			}
		}
		if (gadget* parent = gadget_of(g->parent)) {
			for (uint32_t k = 0; k < parent->kids.size; k++) {
				if (parent->kids[k] == handle) {
					for (uint32_t m = k + 1; m < parent->kids.size; m++) {
						parent->kids[m - 1] = parent->kids[m];
					}
					parent->kids.size--;
					break;
				}
			}
		}
		if (active_window() == handle) {
			set_active_window(0, false);
		}
		if (g->surface) {
			bb_gui_window_close(g->surface);
			g->surface = 0;
		}
		bb_free(g->text);
		g->text = nullptr;
		for (uint32_t i = 0; i < g->items.size; i++) {
			bb_free(g->items[i].text);
		}
		g->items.release();
		g->kids.release();
		g->formats.release();
		g->tool_enabled.release();
		bb_free(g->tips);
		g->tips = nullptr;
		bb_free(g->status);
		g->status = nullptr;
		if (g->root) {
			free_node(g->root);
		}
		if (g->menu) {
			free_menu_tree(g->menu);
		}
		if (g->canvas_image) {
			bb_free_internal_image(g->canvas_image); // The pictures of a canvas are the runtime's own, its image too.
			bb_free_internal_image(g->image);
		} else if (g->image) {
			bb_free_image(g->image);
		}
		if (g->picture) {
			bb_free_image(g->picture);
		}
		g->used = false;
		dirty();
	}
} // namespace bb::gui

using namespace bb::gui;

extern "C" {

////////////////////////////////////////////////////////////////////////////////
// What all gadgets have
////////////////////////////////////////////////////////////////////////////////
void bb_free_gadget(int32_t handle)
{
	if (!handle) {
		BB_DEBUG_HANDLE_MISSING("FreeGadget", "gadget", handle);
		return;
	}
	need_gadget(handle, "FreeGadget");
	if (handle == desktop_handle()) {
		gui_error("FreeGadget: the desktop can't be freed.");
	}
	free_gadget_tree(handle);
}

void bb_set_gadget_font(int32_t handle, int32_t font)
{
	gadget* g = need_gadget(handle, "SetGadgetFont");
	g->font   = font;
	dirty();
}

void bb_set_gadget_text(int32_t handle, const char* text)
{
	gadget* g = need_gadget(handle, "SetGadgetText");
	switch (g->kind) {
	case K_TEXTFIELD:
		set_text_field(*g, text);
		break;
	case K_TEXTAREA:
		text_area_insert(*g, 0, text_area_length(*g), text);
		break;
	default:
		set_string(g->text, text);
		if ((g->kind == K_WINDOW) && g->surface) {
			bb_gui_window_set_title(g->surface, g->text);
		}
		break;
	}
	dirty();
}

void bb_set_gadget_shape(int32_t handle, int32_t x, int32_t y, int32_t w, int32_t h)
{
	gadget* g = need_gadget(handle, "SetGadgetShape");
	if (g->kind == K_DESKTOP) {
		gui_error("SetGadgetShape: the desktop can't be changed.");
	}
	if (g->kind == K_WINDOW) {
		// What was asked for is the size of the client area for windows with style 32.
		if (g->style & 32) {
			int l, t, r, b;
			window_decoration(*g, &l, &t, &r, &b);
			w += l + r;
			h += t + b;
		}
		if (g->maximized || g->minimized) {
			g->maximized = g->minimized = false;
		}
		// A window can't be made smaller than SetMinWindowSize says, which is the size with the frame.
		if (w < g->min_w) {
			w = g->min_w;
		}
		if (h < g->min_h) {
			h = g->min_h;
		}
	}
	set_shape(handle, x, y, w, h);
	lock_layout(*gadget_of(handle));
}

void bb_set_gadget_layout(int32_t handle, int32_t left, int32_t right, int32_t top, int32_t bottom)
{
	gadget* g = need_gadget(handle, "SetGadgetLayout");
	g->left   = left;
	g->right  = right;
	g->top    = top;
	g->bottom = bottom;
	lock_layout(*g);
}

void bb_show_gadget(int32_t handle)
{
	gadget* g = need_gadget(handle, "ShowGadget");
	g->visible = true;
	if (g->surface) {
		bb_gui_window_show(g->surface, 1);
	}
	dirty();
}

void bb_hide_gadget(int32_t handle)
{
	gadget* g = need_gadget(handle, "HideGadget");
	g->visible = false;
	if (g->surface) {
		bb_gui_window_show(g->surface, 0);
	}
	dirty();
}

void bb_enable_gadget(int32_t handle)
{
	gadget* g = need_gadget(handle, "EnableGadget");
	g->enabled = true;
	dirty();
}

void bb_disable_gadget(int32_t handle)
{
	gadget* g = need_gadget(handle, "DisableGadget");
	g->enabled = false;
	dirty();
}

int32_t bb_gadget_font(int32_t handle)
{
	return need_gadget(handle, "GadgetFont")->font;
}

const char* bb_gadget_text(int32_t handle)
{
	gadget* g = need_gadget(handle, "GadgetText");
	if (g->kind == K_TEXTAREA) {
		return string_result(g->text);
	}
	return string_result(g->text);
}

int32_t bb_gadget_x(int32_t handle)
{
	return need_gadget(handle, "GadgetX")->x;
}

int32_t bb_gadget_y(int32_t handle)
{
	return need_gadget(handle, "GadgetY")->y;
}

int32_t bb_gadget_width(int32_t handle)
{
	gadget* g = need_gadget(handle, "GadgetWidth");
	if (g->kind == K_DESKTOP) {
		int w, h;
		screen_size(&w, &h);
		return w;
	}
	return g->w;
}

int32_t bb_gadget_height(int32_t handle)
{
	gadget* g = need_gadget(handle, "GadgetHeight");
	if (g->kind == K_DESKTOP) {
		int w, h;
		screen_size(&w, &h);
		return h;
	}
	return g->h;
}

int32_t bb_gadget_group(int32_t handle)
{
	return need_gadget(handle, "GadgetGroup")->parent;
}

int32_t bb_client_width(int32_t handle)
{
	gadget* g = need_gadget(handle, "ClientWidth");
	int x, y, w, h;
	if (g->kind == K_DESKTOP) {
		screen_size(&w, &h);
		return w;
	}
	client_rect(handle, &x, &y, &w, &h);
	return w;
}

int32_t bb_client_height(int32_t handle)
{
	gadget* g = need_gadget(handle, "ClientHeight");
	int x, y, w, h;
	if (g->kind == K_DESKTOP) {
		screen_size(&w, &h);
		return h;
	}
	client_rect(handle, &x, &y, &w, &h);
	return h;
}

// What the system has for a gadget: the window it is in (1 and 2), which is the one window of the program. There is no
// handle for fonts (3), or for what is not a gadget.
// 1 and 2 are the window of the computer that the gadget is in, which is the window of its window where that has one of its
// own, and the window of Graphics for the rest. There is no handle of the system to be had for them.
int32_t bb_gui_query(int32_t handle, int32_t query)
{
	if (!gadget_of(handle) || ((query != 1) && (query != 2))) {
		return 0;
	}
	if (int32_t surface = bb_gui_window_surface(handle)) {
		return surface;
	}
	return bb_native_window();
}

int32_t bb_desktop(void)
{
	gui_used = true;
	ensure_graphics();
	return desktop_handle();
}
}

extern "C" {
// The buffer of the desktop, which has nothing to draw on or read from.
int32_t bb_desktop_buffer(void)
{
	gui_used = true;
	ensure_graphics();
	return bb::gui::desktop_buffer();
}

////////////////////////////////////////////////////////////////////////////////
// What the graphics side asks (graphics_input.cpp): the windows of the computer and what is in them.
////////////////////////////////////////////////////////////////////////////////
// Whether the program made gadgets, which is when closing the window of Graphics is for the program to answer.
int32_t bb_gui_used(void)
{
	return gui_used ? 1 : 0;
}

// Where a window of the computer is on the desktop of the GUI, which is where the mouse in it is for the program. 0 for one
// that has no gadget any more, or whose gadget is hidden.
int32_t bb_gui_window_origin(int32_t window, int32_t* x, int32_t* y)
{
	gadget* g = gadget_of(gadget_of_surface(window));
	if (!g || !g->visible) {
		return 0;
	}
	*x = g->x;
	*y = g->y;
	return 1;
}

// The window of the computer that a gadget is in, 0 for one on the desktop of the window of Graphics.
int32_t bb_gui_window_surface(int32_t handle)
{
	gadget* w = gadget_of(window_of(handle));
	return w ? w->surface : 0;
}
}
